-- ============================================================
-- 步2: 7B/U7 完形 2 篇 (定稿;每篇8空, questions jsonb)
-- 第1篇答案 CDCBCACB(保持);第2篇原全A→已打散(词不变,只调ABCD位置)
-- 幂等 WHERE NOT EXISTS by title; ⚠️先跑步1建表
-- ============================================================

INSERT INTO junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order)
SELECT 'b1c2d3e4-0a1b-4c2d-8e3f-9a0b1c2d3e40', 7, '7B', 'U7', '七下 U7 完形:Our School Trip Yesterday', 'Yesterday (1)____ a special day for the students in Class 1. We (2)____ a school trip to the Science Museum. We met at the school gate at 8:00 a.m. and (3)____ the bus there. The museum was very big. We (4)____ many interesting robots inside. They could talk to people! Tom (5)____ take photos because he lost his camera. He was a bit sad. But our teacher helped him. We ate our lunch (6)____ a big tree outside the museum. We (7)____ very happy all day. We (8)____ back home at 4:00 p.m. It was a wonderful trip!', 98, 3, '[{"q":"1","options":["is","am","was","were"],"answer":"C","explanation":"Yesterday 时间状语,主语 a special day 是单数,be 动词过去式→**was**。"},{"q":"2","options":["have","has","having","had"],"answer":"D","explanation":"have 的不规则过去式→**had**(had a school trip 进行了一次校游)。"},{"q":"3","options":["take","takes","took","taking"],"answer":"C","explanation":"与 met 并列用过去式;take the bus 坐公交→**took**。"},{"q":"4","options":["see","saw","sees","seeing"],"answer":"B","explanation":"see 的不规则过去式→**saw**(看见了许多机器人)。"},{"q":"5","options":["don''t","doesn''t","didn''t","isn''t"],"answer":"C","explanation":"过去时否定:**didn’t** + 动词原形 take(丢了相机,没能拍照)。"},{"q":"6","options":["under","on","in","from"],"answer":"A","explanation":"在树下用 **under**:under a big tree。"},{"q":"7","options":["are","was","were","been"],"answer":"C","explanation":"主语 We 是复数,be 动词过去式→**were**(We were happy)。"},{"q":"8","options":["go","went","goes","going"],"answer":"B","explanation":"go 的不规则过去式→**went**(went back home 回家)。"}]'::jsonb, 1
WHERE NOT EXISTS (SELECT 1 FROM junior_cloze WHERE title = '七下 U7 完形:Our School Trip Yesterday');

INSERT INTO junior_cloze (id, grade, volume, unit, title, body, word_count, difficulty, questions, sort_order)
SELECT 'b2c3d4e5-1a2b-4c3d-8e4f-9a1b2c3d4e51', 7, '7B', 'U7', '七下 U7 完形:A Wonderful Weekend on the Farm', 'Last weekend, Lucy went to her grandpa''s farm. She stayed there (1)____ two days and had a great time. On Saturday morning, she (2)____ early because the birds sang happily outside. After breakfast, she helped her grandpa. She gave water (3)____ the chickens. In the afternoon, she rode a (4)____ with her cousin. It was her first time, so she was a bit afraid, but she loved the animal. On Sunday, they went to a small river near the farm. They swam in the clean (5)____. For dinner, they enjoyed some food. Lucy (6)____ her grandpa for his kindness and (7)____ the farm on Sunday evening. She wants to (8)____ there again next month.', 114, 3, '[{"q":"1","options":["at","for","on","in"],"answer":"B","explanation":"stay **for** + 时间段:stayed there for two days(待了两天)。"},{"q":"2","options":["slept","ran","sat","woke up"],"answer":"D","explanation":"被鸟叫吵醒早起:wake up 的过去式→**woke up**。"},{"q":"3","options":["to","from","in","on"],"answer":"A","explanation":"give sth **to** sb:give water to the chickens(给鸡喂水)。"},{"q":"4","options":["bird","chicken","horse","fish"],"answer":"C","explanation":"ride a **horse**=骑马(固定搭配)。"},{"q":"5","options":["water","tree","grass","desk"],"answer":"A","explanation":"在河里游泳→swam in the **water**(干净的水里)。"},{"q":"6","options":["lost","forgot","changed","thanked"],"answer":"D","explanation":"thank sb for sth:Lucy **thanked** her grandpa(感谢爷爷的好意)。"},{"q":"7","options":["found","left","liked","saw"],"answer":"B","explanation":"leave 的过去式→**left**(left the farm 离开农场)。"},{"q":"8","options":["went","goes","go","going"],"answer":"C","explanation":"want **to** + 动词原形→to **go**(想下个月再去)。"}]'::jsonb, 2
WHERE NOT EXISTS (SELECT 1 FROM junior_cloze WHERE title = '七下 U7 完形:A Wonderful Weekend on the Farm');

-- 校验(单独跑): 应 2 行, 各 8 空
SELECT volume, unit, title, word_count, difficulty, jsonb_array_length(questions) AS blanks FROM junior_cloze WHERE volume='7B' AND unit='U7' ORDER BY sort_order;
-- END OF FILE u7-cloze.sql
